// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(to != address(0));
        // adversarial-but-cooperative counterparty: a token whose transferFrom succeeds
        OkToken tok = new OkToken();
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool ok = c.transfer(from, address(tok), tos, v);
        assertTrue(ok);
    }
}

contract OkToken {
    function transferFrom(address, address, uint256) external payable returns (bool) {
        return true;
    }
}
